/* Shoe meshes and remapped UVs adapted from the licensed reference diners.
   See vendor/Guest-credits.txt. Bake the shared swatches with guest_footwear.py. */
(function(global){
  'use strict';
  const shapes={"a":{"p":"","n":"","uv":"","i":"","span":[0.08244475722312927,0.10726599395275116,0.22050440311431885]},"b":{"p":"","n":"","uv":"","i":"","span":[0.08647904545068741,0.15816181898117065,0.20589867234230042]},"c":{"p":"","n":"","uv":"","i":"","span":[0.08647904545068741,0.15816181898117065,0.20589867234230042]}}; // baked shoe lasts
  // Source last, overall width/height/length and the resting pigment of the upper.
  const styles=[
    ['a',.192,.175,.347,'#D5C6A8'],['a',.167,.179,.332,'#694F55'],['a',.159,.166,.339,'#967065'],
    ['b',.196,.245,.350,'#926647'],['a',.180,.178,.324,'#D8CFBB'],['a',.178,.184,.315,'#82574B'],
    ['b',.175,.195,.344,'#544956'],['b',.188,.220,.338,'#766446'],['c',.166,.192,.353,'#466764'],
    ['b',.182,.232,.329,'#AB8C6F'],['a',.179,.180,.344,'#78594C']
  ];
  const decoded={},materials=new WeakMap(),pending=new Set();
  let texture,loading=false;
  function array(raw,Type){return new Type(Uint8Array.from(atob(raw),c=>c.charCodeAt(0)).buffer);}
  function shoe(key){
    if(!decoded[key]){
      const s=shapes[key];
      decoded[key]={p:array(s.p,Int16Array),n:array(s.n,Int8Array),uv:array(s.uv,Uint16Array),tri:array(s.i,Uint16Array),span:s.span};
    }
    return decoded[key];
  }
  function refine(id,parts,T){
    const style=styles[id-2];if(!style)return;
    const [key,w,h,length,tone]=style,src=shoe(key),tile=id-2;
    const colour=new T.Color(tone).convertSRGBToLinear(),rubber=new T.Color('#8C8171').convertSRGBToLinear();
    for(const side of [-1,1]){
      const pos=new Float32Array(src.p.length),norm=new Float32Array(pos.length),colors=new Float32Array(pos.length);
      const uv=new Float32Array(src.uv.length),tri=src.tri.slice(),normal=new T.Vector3(),tint=new T.Color();
      for(let i=0;i<pos.length;i+=3){
        const x=src.p[i]/32767-.5,y=src.p[i+1]/32767,z=src.p[i+2]/32767;
        // Counter-splay at the heel locates the shaft directly on its ankle joint.
        pos[i]=side*(.128+w*x);pos[i+1]=.01+y*h;pos[i+2]=-.105+z*length;
        normal.set(side*src.n[i]*src.span[0]/w,src.n[i+1]*src.span[1]/h,src.n[i+2]*src.span[2]/length).normalize();
        normal.toArray(norm,i);
        tint.copy(y<.16?rubber:colour).toArray(colors,i);
        const j=i/3*2;
        uv[j]=(tile%4+(.75+510.5*src.uv[j]/65535)/512)/4;
        uv[j+1]=1-(Math.floor(tile/4)+(.75+510.5*src.uv[j+1]/65535)/512)/4;
      }
      if(side<0)for(let i=0;i<tri.length;i+=3){const old=tri[i+1];tri[i+1]=tri[i+2];tri[i+2]=old;}
      const mesh=new T.BufferGeometry();
      mesh.setAttribute('position',new T.BufferAttribute(pos,3));mesh.setAttribute('normal',new T.BufferAttribute(norm,3));
      mesh.setAttribute('color',new T.BufferAttribute(colors,3));mesh.setAttribute('uv',new T.BufferAttribute(uv,2));
      mesh.setIndex(new T.BufferAttribute(tri,1));mesh.computeBoundingSphere();mesh.userData.shoe=true;
      parts['foot'+side].dispose();parts['foot'+side]=mesh;
    }
  }
  function mapReady(mat){
    mat.map=texture;mat.vertexColors=false;mat.needsUpdate=true;
  }
  function material(geometry,base,T){
    if(!geometry?.userData.shoe||!global.document)return base;
    if(materials.has(base))return materials.get(base);
    const mat=base.clone();mat.roughness=.78;mat.alphaTest=.28;mat.side=T.DoubleSide;
    materials.set(base,mat);
    if(texture){mapReady(mat);return mat;}
    pending.add(mat);
    if(!loading){
      loading=true;
      new T.TextureLoader().load(global.DinerArtData?.footwear||'art/guest-footwear.png',image=>{
        image.encoding=T.sRGBEncoding;image.anisotropy=4;texture=image;
        for(const m of pending)mapReady(m);
        pending.clear();global.dispatchEvent(new Event('diner-model-ready'));
      },undefined,()=>pending.clear());
    }
    return mat;
  }
  global.DinerGuestFootwear=Object.freeze({refine,material});
})(window);
